from pathlib import Path
from collections import Counter
from urllib.parse import urlparse, unquote
import gzip, hashlib, json, math, re, sqlite3, sys

ROOT = Path(__file__).resolve().parent
INPUT = Path('/tmp/jstack-trace-input-20261016')
DB = ROOT / 'profiles.sqlite'
VALIDATION = {'profiles': {}, 'errors': [], 'warnings': [], 'convention': 'self_* and inclusive_* group timeDeltas[i] with samples[i]. This is a computational convention for recorded deltas, not measured self CPU duration. timeDeltas[i] spans the preceding sample to sample i; the first spans profile start to sample 0. No final tail is attributed.'}

def encode(value):
    return json.dumps(value, ensure_ascii=False, separators=(',', ':'), allow_nan=False)

def fail(message):
    VALIDATION['errors'].append(message)
    (ROOT / 'validation.json').write_text(json.dumps(VALIDATION, indent=2) + '\n')
    raise ValueError(message)

def require(condition, message):
    if not condition:
        fail(message)

def integer(value):
    return type(value) is int

def unique_object(pairs):
    result = {}
    for key, value in pairs:
        require(key not in result, f'duplicate JSON property {key}')
        result[key] = value
    return result

require(not DB.exists(), 'Database already exists. Preserve it and select a new owned run directory for reruns.')
conn = sqlite3.connect(DB)
conn.executescript((ROOT / 'schema.sql').read_text())
source_lines = (INPUT / 'report.js').read_text().splitlines()
for profile, filename in [('before', 'before.cpuprofile'), ('after', 'after.cpuprofile.gz')]:
    raw = (INPUT / filename).read_bytes()
    data_bytes = gzip.decompress(raw) if filename.endswith('.gz') else raw
    data = json.loads(data_bytes, object_pairs_hook=unique_object)
    require(isinstance(data, dict), f'{profile}: root must be object')
    for field in ['nodes', 'startTime', 'endTime', 'samples', 'timeDeltas']:
        require(field in data, f'{profile}: required analysis input missing {field}')
    nodes, samples, deltas = data['nodes'], data['samples'], data['timeDeltas']
    require(isinstance(nodes, list) and len(nodes)>0, f'{profile}: nodes must be nonempty array')
    require(isinstance(samples, list) and isinstance(deltas, list), f'{profile}: samples and deltas must be arrays')
    require(len(samples)==len(deltas), f'{profile}: samples/timeDeltas length mismatch')
    start, end = data['startTime'], data['endTime']
    require(all(type(v) in (float,int) and math.isfinite(v) for v in [start,end]) and 0<=start<=end, f'{profile}: invalid duration bounds')
    by_id, parents, keys = {}, {}, {}
    for node in nodes:
        require(isinstance(node,dict) and integer(node.get('id')), f'{profile}: invalid node id')
        nid = node['id']
        require(nid not in by_id, f'{profile}: duplicate node id {nid}')
        by_id[nid] = node
        frame = node.get('callFrame')
        require(isinstance(frame,dict), f'{profile}/{nid}: callFrame must be object')
        require(all(isinstance(frame.get(k),str) for k in ['functionName','url','scriptId']), f'{profile}/{nid}: invalid frame strings')
        require(all(integer(frame.get(k)) and frame[k]>=-1 for k in ['lineNumber','columnNumber']), f'{profile}/{nid}: invalid zero-based frame coordinates')
        require('hitCount' not in node or integer(node['hitCount']) and node['hitCount']>=0, f'{profile}/{nid}: invalid hitCount')
        require(isinstance(node.get('children',[]),list), f'{profile}/{nid}: children must be array')
        keys[nid] = encode([frame['url'],frame['functionName'],frame['lineNumber'],frame['columnNumber']])
    for node in nodes:
        for child in node.get('children',[]):
            require(integer(child) and child in by_id, f'{profile}/{node["id"]}: unknown child {child}')
            require(child not in parents, f'{profile}: duplicate edge or multiple parents for {child}')
            parents[child] = node['id']
    roots = set(by_id)-set(parents)
    require(len(roots)==1 and nodes[0]['id'] in roots, f'{profile}: must have one root, first node')
    root_id = nodes[0]['id']
    chains = {}
    for nid in by_id:
        chain, seen, current = [], set(), nid
        while True:
            require(current not in seen, f'{profile}: cycle through {current}')
            chain.append(current)
            seen.add(current)
            if current not in parents:
                require(current==root_id, f'{profile}: disconnected node {nid}')
                break
            current = parents[current]
        chains[nid] = list(reversed(chain))
    require(all(integer(n) and n in by_id for n in samples), f'{profile}: invalid sample node reference')
    require(all(integer(d) and d>=0 for d in deltas), f'{profile}: invalid delta')
    weight = sum(deltas)
    require(weight<=end-start, f'{profile}: cumulative deltas exceed duration')
    tail = end-start-weight
    if tail:
        VALIDATION['warnings'].append({'profile':profile,'kind':'unattributed_tail','microseconds':tail})
    if not samples or not weight:
        VALIDATION['warnings'].append({'profile':profile,'kind':'empty_or_zero_weight_samples'})
    counts = Counter(samples)
    collisions = {key: [nid for nid in by_id if keys[nid]==key] for key,c in Counter(keys.values()).items() if c>1}
    if collisions:
        VALIDATION['warnings'].append({'profile':profile,'kind':'repeated_stable_frame','nodes':collisions,'detail':'Node and path queries retain contexts. Frame-inclusive query counts each sample once per stable frame.'})
    hit_mismatches = [{'node_id':n['id'],'hitCount':n['hitCount'],'sample_count':counts[n['id']]} for n in nodes if 'hitCount' in n and n['hitCount']!=counts[n['id']]]
    if hit_mismatches:
        VALIDATION['warnings'].append({'profile':profile,'kind':'hit_count_mismatch','nodes':hit_mismatches})
    conn.execute('INSERT INTO profiles VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)', (profile,str(INPUT/filename),hashlib.sha256(raw).hexdigest(),hashlib.sha256(data_bytes).hexdigest(),start,end,end-start,len(samples),len(deltas),weight,tail,root_id,encode({k:v for k,v in data.items() if k not in ['nodes','samples','timeDeltas','startTime','endTime']})))
    for ordinal,node in enumerate(nodes):
        nid,frame = node['id'],node['callFrame']
        conn.execute('INSERT OR IGNORE INTO frames VALUES(?,?,?,?,?)', (keys[nid],frame['functionName'],frame['url'],frame['lineNumber'],frame['columnNumber']))
        conn.execute('INSERT INTO nodes VALUES(?,?,?,?,?,?,?)',(profile,nid,ordinal,keys[nid],frame['scriptId'],node.get('hitCount'),encode({k:v for k,v in node.items() if k not in ['id','children']})))
    for node in nodes:
        for ordinal,child in enumerate(node.get('children',[])):
            conn.execute('INSERT INTO edges VALUES(?,?,?,?)',(profile,node['id'],child,ordinal))
    elapsed = start
    for i in range(len(samples)):
        elapsed += deltas[i]
        require(start<=elapsed<=end, f'{profile}: sample timestamp out of bounds at {i}')
        conn.execute('INSERT INTO samples VALUES(?,?,?,?,?)',(profile,i,samples[i],deltas[i],elapsed))
    for nid,chain in chains.items():
        conn.execute('INSERT INTO paths VALUES(?,?,?,?,?)',(profile,nid,encode(chain),encode([keys[n] for n in chain]),' > '.join(by_id[n]['callFrame']['functionName'] for n in chain)))
        for distance,ancestor in enumerate(reversed(chain)):
            conn.execute('INSERT INTO ancestors VALUES(?,?,?,?)',(profile,ancestor,nid,distance))
        frame = by_id[nid]['callFrame']
        line,col = frame['lineNumber'],frame['columnNumber']
        path_name = Path(unquote(urlparse(frame['url']).path)).name
        source_line, supplied, status, detail = None,None,'unmapped','No supplied source matching this frame URL.'
        if path_name=='report.js':
            supplied = str(INPUT/'report.js')
            if line<0 or col<0 or line>=len(source_lines):
                status,detail = 'coordinate_mismatch','Frame position is unavailable or outside supplied source.'
            else:
                source_line = source_lines[line]
                utf16_units = len(source_line.encode('utf-16-le'))//2
                if col>utf16_units:
                    status,detail = 'coordinate_mismatch','Column exceeds source line UTF-16 length.'
                elif not re.search(r'\bfunction\s+'+re.escape(frame['functionName'])+r'\s*\(',source_line):
                    status,detail = 'symbol_mismatch','Recorded line does not declare recorded function in supplied source.'
                else:
                    status,detail = 'matched_supplied_source','Frame URL basename, symbol and zero-based declaration line match supplied report.js. This mapping does not prove the fixture came from executing that file. Column is checked for bounds, not treated as the exact symbol-token start.'
        elif not frame['url'] and line==-1 and col==-1:
            status,detail = 'pseudo_frame','No source location. Retained in all totals.'
        if status in ['coordinate_mismatch','symbol_mismatch','unmapped']:
            VALIDATION['warnings'].append({'profile':profile,'node_id':nid,'kind':status,'detail':detail})
        conn.execute('INSERT INTO source_mappings VALUES(?,?,?,?,?,?,?,?)',(profile,nid,supplied,line+1 if line>=0 else None,col+1 if col>=0 else None,source_line,status,detail))
    VALIDATION['profiles'][profile] = {'node_count':len(nodes),'edge_count':len(parents),'sample_count':len(samples),'delta_count':len(deltas),'weight_us':weight,'duration_us':end-start,'unattributed_tail_us':tail,'root_id':root_id,'max_depth':max(map(len,chains.values())),'hit_mismatch_count':len(hit_mismatches),'valid_tree':True,'sample_references_valid':True,'timestamp_bounds_valid':True}
conn.commit()
conn.row_factory = sqlite3.Row
results = {}
for name,sql in re.findall(r'-- query: ([^\n]+)\n(.*?)(?=-- query: |\Z)',(ROOT/'queries.sql').read_text(),re.S):
    results[name] = [dict(row) for row in conn.execute(sql)]
(ROOT/'raw-results.json').write_text(json.dumps(results,indent=2)+'\n')
(ROOT/'validation.json').write_text(json.dumps(VALIDATION,indent=2)+'\n')
conn.close()
print(json.dumps({'database':str(DB),'validation':VALIDATION,'query_row_counts':{k:len(v) for k,v in results.items()}},indent=2))

