-- query: profiles
SELECT * FROM profiles ORDER BY profile;
-- query: self_frames
SELECT s.*,f.function_name,f.url,f.line_zero,f.column_zero,100.0*s.weight_us/nullif(p.weight_us,0) weighted_share_pct,100.0*s.sample_count/nullif(p.sample_count,0) count_share_pct FROM self_frames s JOIN frames f USING(frame_key) JOIN profiles p USING(profile) ORDER BY profile,weight_us DESC,frame_key;
-- query: inclusive_frames
SELECT s.*,f.function_name,100.0*s.weight_us/nullif(p.weight_us,0) weighted_share_pct,100.0*s.sample_count/nullif(p.sample_count,0) count_share_pct FROM inclusive_frames s JOIN frames f USING(frame_key) JOIN profiles p USING(profile) ORDER BY profile,weight_us DESC,frame_key;
-- query: exact_paths
SELECT s.profile,s.node_id,p.function_path,p.node_ids_json,p.frame_keys_json,s.sample_count,s.weight_us,100.0*s.weight_us/nullif(t.weight_us,0) weighted_share_pct,100.0*s.sample_count/nullif(t.sample_count,0) count_share_pct,i.weight_us inclusive_weight_us,i.sample_count inclusive_sample_count FROM self_nodes s JOIN paths p USING(profile,node_id) JOIN inclusive_nodes i USING(profile,node_id) JOIN profiles t USING(profile) ORDER BY s.profile,s.weight_us DESC,s.node_id;
-- query: paired_self
SELECT f.*,coalesce(b.weight_us,0) before_us,coalesce(a.weight_us,0) after_us,coalesce(a.weight_us,0)-coalesce(b.weight_us,0) delta_us,coalesce(b.sample_count,0) before_count,coalesce(a.sample_count,0) after_count,100.0*coalesce(b.weight_us,0)/nullif(pb.weight_us,0) before_share_pct,100.0*coalesce(a.weight_us,0)/nullif(pa.weight_us,0) after_share_pct,b.frame_key IS NOT NULL before_present,a.frame_key IS NOT NULL after_present FROM frames f LEFT JOIN self_frames b ON b.frame_key=f.frame_key AND b.profile='before' LEFT JOIN self_frames a ON a.frame_key=f.frame_key AND a.profile='after' JOIN profiles pb ON pb.profile='before' JOIN profiles pa ON pa.profile='after' ORDER BY abs(coalesce(a.weight_us,0)-coalesce(b.weight_us,0)) DESC,f.frame_key;
-- query: paired_inclusive
SELECT f.function_name,f.frame_key,coalesce(b.weight_us,0) before_us,coalesce(a.weight_us,0) after_us,coalesce(a.weight_us,0)-coalesce(b.weight_us,0) delta_us,coalesce(b.sample_count,0) before_count,coalesce(a.sample_count,0) after_count FROM frames f LEFT JOIN inclusive_frames b ON b.frame_key=f.frame_key AND b.profile='before' LEFT JOIN inclusive_frames a ON a.frame_key=f.frame_key AND a.profile='after' ORDER BY abs(coalesce(a.weight_us,0)-coalesce(b.weight_us,0)) DESC,f.frame_key;
-- query: paired_paths
WITH k AS (SELECT DISTINCT frame_keys_json FROM paths), totals AS (SELECT p.profile,p.frame_keys_json,sum(s.weight_us) weight_us,sum(s.sample_count) sample_count FROM paths p JOIN self_nodes s USING(profile,node_id) GROUP BY p.profile,p.frame_keys_json) SELECT k.frame_keys_json,coalesce(b.weight_us,0) before_us,coalesce(a.weight_us,0) after_us,coalesce(a.weight_us,0)-coalesce(b.weight_us,0) delta_us,coalesce(b.sample_count,0) before_count,coalesce(a.sample_count,0) after_count FROM k LEFT JOIN totals b ON b.frame_keys_json=k.frame_keys_json AND b.profile='before' LEFT JOIN totals a ON a.frame_keys_json=k.frame_keys_json AND a.profile='after' ORDER BY abs(coalesce(a.weight_us,0)-coalesce(b.weight_us,0)) DESC,k.frame_keys_json;
-- query: mappings
SELECT m.*,f.function_name,f.url,f.line_zero,f.column_zero FROM source_mappings m JOIN nodes n USING(profile,node_id) JOIN frames f USING(frame_key) ORDER BY profile,node_id;
-- query: hit_count_mismatches
SELECT n.profile,n.node_id,n.hit_count,s.sample_count FROM nodes n JOIN self_nodes s USING(profile,node_id) WHERE n.hit_count IS NOT NULL AND n.hit_count!=s.sample_count;
-- query: delta_distribution
SELECT profile,delta_us,count(*) samples,sum(delta_us) weight_us FROM samples GROUP BY profile,delta_us ORDER BY profile,delta_us;
-- query: sample_bounds
SELECT profile,min(sample_index) first_index,max(sample_index) last_index,min(timestamp_us) first_timestamp_us,max(timestamp_us) last_timestamp_us,count(*) sample_count,sum(delta_us) weight_us FROM samples GROUP BY profile;
-- query: integrity
PRAGMA integrity_check;
-- query: foreign_keys
PRAGMA foreign_key_check;

parser/schema.sql.text:
PRAGMA foreign_keys = ON;
CREATE TABLE profiles(profile TEXT PRIMARY KEY, input_path TEXT, input_sha256 TEXT, decompressed_sha256 TEXT, start_us NUMERIC, end_us NUMERIC, duration_us NUMERIC, sample_count INTEGER, delta_count INTEGER, weight_us INTEGER, tail_us NUMERIC, root_id INTEGER, extras_json TEXT);
CREATE TABLE frames(frame_key TEXT PRIMARY KEY, function_name TEXT, url TEXT, line_zero INTEGER, column_zero INTEGER);
CREATE TABLE nodes(profile TEXT, node_id INTEGER, ordinal INTEGER, frame_key TEXT, script_id TEXT, hit_count INTEGER, extras_json TEXT, PRIMARY KEY(profile,node_id), FOREIGN KEY(profile) REFERENCES profiles, FOREIGN KEY(frame_key) REFERENCES frames);
CREATE TABLE edges(profile TEXT, parent_id INTEGER, child_id INTEGER, child_ordinal INTEGER, PRIMARY KEY(profile,parent_id,child_id), UNIQUE(profile,child_id), FOREIGN KEY(profile,parent_id) REFERENCES nodes(profile,node_id), FOREIGN KEY(profile,child_id) REFERENCES nodes(profile,node_id));
CREATE TABLE samples(profile TEXT, sample_index INTEGER, node_id INTEGER, delta_us INTEGER CHECK(delta_us>=0), timestamp_us NUMERIC, PRIMARY KEY(profile,sample_index), FOREIGN KEY(profile,node_id) REFERENCES nodes(profile,node_id));
CREATE INDEX samples_node ON samples(profile,node_id);
CREATE TABLE ancestors(profile TEXT, ancestor_id INTEGER, descendant_id INTEGER, distance INTEGER, PRIMARY KEY(profile,ancestor_id,descendant_id), FOREIGN KEY(profile,ancestor_id) REFERENCES nodes(profile,node_id), FOREIGN KEY(profile,descendant_id) REFERENCES nodes(profile,node_id));
CREATE TABLE paths(profile TEXT, node_id INTEGER, node_ids_json TEXT, frame_keys_json TEXT, function_path TEXT, PRIMARY KEY(profile,node_id), FOREIGN KEY(profile,node_id) REFERENCES nodes(profile,node_id));
CREATE TABLE source_mappings(profile TEXT, node_id INTEGER, supplied_path TEXT, line_one INTEGER, column_one INTEGER, source_line TEXT, status TEXT, detail TEXT, PRIMARY KEY(profile,node_id), FOREIGN KEY(profile,node_id) REFERENCES nodes(profile,node_id));
CREATE VIEW self_nodes AS SELECT n.profile,n.node_id,n.frame_key,count(s.sample_index) sample_count,coalesce(sum(s.delta_us),0) weight_us FROM nodes n LEFT JOIN samples s ON n.profile=s.profile AND n.node_id=s.node_id GROUP BY n.profile,n.node_id;
CREATE VIEW inclusive_nodes AS SELECT n.profile,n.node_id,n.frame_key,count(s.sample_index) sample_count,coalesce(sum(s.delta_us),0) weight_us FROM nodes n JOIN ancestors a ON a.profile=n.profile AND a.ancestor_id=n.node_id LEFT JOIN samples s ON s.profile=a.profile AND s.node_id=a.descendant_id GROUP BY n.profile,n.node_id;
CREATE VIEW self_frames AS SELECT profile,frame_key,sum(sample_count) sample_count,sum(weight_us) weight_us FROM self_nodes GROUP BY profile,frame_key;
CREATE VIEW inclusive_frames AS SELECT q.profile,q.frame_key,count(s.sample_index) sample_count,coalesce(sum(s.delta_us),0) weight_us FROM (SELECT DISTINCT a.profile,n.frame_key,a.descendant_id FROM ancestors a JOIN nodes n ON n.profile=a.profile AND n.node_id=a.ancestor_id) q LEFT JOIN samples s ON s.profile=q.profile AND s.node_id=q.descendant_id GROUP BY q.profile,q.frame_key;

