-- query: previous_sample_delta_grouping
WITH weights AS (SELECT s.profile,previous.node_id,s.delta_us FROM samples s JOIN samples previous ON previous.profile=s.profile AND previous.sample_index=s.sample_index-1), totals AS (SELECT profile,sum(delta_us) weight_us FROM weights GROUP BY profile), framesum AS (SELECT w.profile,n.frame_key,sum(w.delta_us) weight_us,count(*) intervals FROM weights w JOIN nodes n USING(profile,node_id) GROUP BY w.profile,n.frame_key) SELECT v.*,f.function_name,100.0*v.weight_us/nullif(t.weight_us,0) previous_group_share_pct FROM framesum v JOIN frames f USING(frame_key) JOIN totals t USING(profile) ORDER BY profile,weight_us DESC,frame_key;
-- query: previous_sample_paths
SELECT w.profile,p.function_path,sum(w.delta_us) weight_us,count(*) intervals FROM samples w JOIN samples prev ON prev.profile=w.profile AND prev.sample_index=w.sample_index-1 JOIN paths p ON p.profile=prev.profile AND p.node_id=prev.node_id GROUP BY w.profile,p.frame_keys_json ORDER BY w.profile,weight_us DESC;
-- query: previous_sample_inclusive
WITH weights AS (SELECT s.profile,previous.node_id,s.delta_us FROM samples s JOIN samples previous ON previous.profile=s.profile AND previous.sample_index=s.sample_index-1), membership AS (SELECT DISTINCT a.profile,n.frame_key,a.descendant_id FROM ancestors a JOIN nodes n ON n.profile=a.profile AND n.node_id=a.ancestor_id) SELECT w.profile,m.frame_key,f.function_name,sum(w.delta_us) weight_us,count(*) intervals FROM weights w JOIN membership m ON m.profile=w.profile AND m.descendant_id=w.node_id JOIN frames f USING(frame_key) GROUP BY w.profile,m.frame_key ORDER BY w.profile,weight_us DESC,m.frame_key;
-- query: unassigned_boundaries
SELECT p.profile,s.delta_us first_delta_us,p.tail_us final_tail_us,p.weight_us-s.delta_us previous_group_total_us,p.duration_us FROM profiles p JOIN samples s ON s.profile=p.profile AND s.sample_index=0 ORDER BY p.profile;
-- query: transitions
SELECT s.profile,fprev.function_name previous_function,f.function_name current_function,count(*) intervals,sum(s.delta_us) weight_us FROM samples s JOIN samples prev ON prev.profile=s.profile AND prev.sample_index=s.sample_index-1 JOIN nodes n ON n.profile=s.profile AND n.node_id=s.node_id JOIN frames f ON f.frame_key=n.frame_key JOIN nodes nprev ON nprev.profile=prev.profile AND nprev.node_id=prev.node_id JOIN frames fprev ON fprev.frame_key=nprev.frame_key GROUP BY s.profile,nprev.frame_key,n.frame_key ORDER BY s.profile,weight_us DESC;

